from typing import List
import chunk

def get_chunk_ids(file_path: str, min_size: int) -> List[str]:
    chunk_ids = []
    try:
        with open(file_path, 'rb') as f:
            while True:
                try:
                    ch = chunk.Chunk(f)
                    if ch.getsize() >= min_size:
                        chunk_ids.append(ch.getname().decode('utf-8'))
                    ch.skip()
                except EOFError:
                    break
    except (OSError, IOError) as e:
        # Return an empty list if there are any issues with file access or chunk reading
        return []
    return chunk_ids
